from cardio_1 import a, G
from cardio_2 import t
# J60 — Pneumoconioses (P-02-Pneumologie) : clés propres au cours, absentes des glossaires canoniques et des glossaires de travail P-02 au 08.10.2026.
a('Suva',[('Suva','SUVA, de « Schweizerische Unfallversicherungsanstalt » : Caisse nationale suisse d’assurance en cas d’accidents ; le nom s’écrit aujourd’hui comme un mot, non strictement lettre à lettre')],'Caisse nationale suisse d’assurance en cas d’accidents (Suva)','<p>Assureur-accidents obligatoire des branches à risque et organe d’exécution de la prévention des maladies professionnelles en Suisse. Elle reconnaît et indemnise les maladies professionnelles, prescrit les examens préventifs de médecine du travail et rend les décisions d’aptitude ou d’inaptitude.</p>','j60-annonce')
a('LAA',[('L','Loi fédérale sur l’'),('A','Assurance-'),('A','Accidents')],'Loi fédérale sur l’assurance-accidents (recueil systématique du droit fédéral, 832.20)','<p>Loi qui assimile la maladie professionnelle à un accident professionnel (art. 9) et fixe les obligations de prévention de l’employeur (art. 82). Version consultée : état au 1er janvier 2026, fedlex.admin.ch.</p>','j60-laa')
a('OLAA',[('O','Ordonnance d’exécution de la'),('LAA','Loi sur l’Assurance-Accidents ; sigle officiel, non strictement lettre à lettre du titre « Ordonnance sur l’assurance-accidents »')],'Ordonnance sur l’assurance-accidents (recueil systématique du droit fédéral, 832.202)','<p>Ordonnance d’exécution de la LAA. Son annexe 1 (art. 14) énumère les substances nocives et les affections dues à certains travaux qui fondent une maladie professionnelle « de liste ». Version consultée : état au 1er janvier 2026.</p>','j60-laa')
a('OPA',[('O','Ordonnance sur la'),('P','Prévention des'),('A','Accidents et des maladies professionnelles')],'Ordonnance sur la prévention des accidents et des maladies professionnelles (recueil systématique du droit fédéral, 832.30)','<p>Ordonnance qui organise la médecine du travail préventive : assujettissement, examens d’embauche et de contrôle, décision d’inaptitude (art. 70 à 78) et indemnité pour changement d’occupation (art. 86).</p>','j60-opa')
a('ILO',[('I','International'),('L','Labour'),('O','Organization (Organisation internationale du Travail)')],'International Labour Organization (Organisation internationale du Travail)','<p>Institution des Nations unies qui publie la classification internationale des radiographies de pneumoconioses ; édition révisée de 2022 avec images numériques de référence.</p>','j60-ilo')
a('VME',[('V','Valeur'),('M','Moyenne d’'),('E','Exposition')],'Valeur moyenne d’exposition','<p>Concentration moyenne d’une substance dans l’air du poste de travail, calculée sur huit heures par jour et quarante-deux heures par semaine, qui ne nuit pas à la santé de la grande majorité des travailleurs selon l’état des connaissances. La Suva publie la liste suisse des valeurs limites.</p>','j60-vme')
a('IGRA',[('I','Interferon-'),('G','Gamma'),('R','Release'),('A','Assay')],'Test de libération d’interféron gamma','<p>Test sanguin qui mesure l’interféron gamma libéré par les lymphocytes T mis en contact avec des antigènes spécifiques de <i>Mycobacterium tuberculosis</i>. Il détecte une infection tuberculeuse sans distinguer infection et maladie active.</p>','j60-igra')
a('BeLPT',[('Be','Beryllium (béryllium)'),('L','Lymphocyte'),('P','Proliferation'),('T','Test')],'Test de prolifération lymphocytaire au béryllium','<p>Test qui met en culture les lymphocytes du sang ou du lavage bronchoalvéolaire avec des sels de béryllium et mesure leur prolifération. Un résultat anormal confirmé signe une sensibilisation au béryllium (ATS 2014).</p>','j60-belpt')
a('EFA',[('E','Entschädigungsfonds (fonds d’indemnisation)'),('F','für (pour les)'),('A','Asbestopfer (victimes de l’amiante)')],'Fondation Fonds d’indemnisation des victimes de l’amiante','<p>Fondation suisse créée en 2017 qui indemnise surtout les personnes atteintes d’un mésothéliome dû à l’amiante sans couverture par l’assurance-accidents, par exemple après une exposition domestique ou environnementale.</p>','j60-efa')
a('SiO₂',[('Si','Silicium'),('O₂','deux atomes d’Oxygène')],'Dioxyde de silicium (silice)','<p>Formule de la silice. Sous forme cristalline (quartz, cristobalite, tridymite), elle est fibrogène et cancérogène ; sous forme amorphe, elle est beaucoup moins toxique.</p>','j60-silice')
a('HLA-DPB1',[('HLA','Human Leukocyte Antigen (antigène leucocytaire humain)'),('DP','locus DP de classe II'),('B','chaîne Bêta'),('1','gène 1')],'Gène de la chaîne bêta 1 de la molécule HLA-DP','<p>Gène du complexe majeur d’histocompatibilité de classe II. Le variant qui porte un glutamate en position 69 présente le béryllium aux lymphocytes T CD4 et augmente le risque de bérylliose chronique.</p>','j60-berylliose')
a('ATF',[('A','Arrêt du'),('T','Tribunal'),('F','Fédéral')],'Arrêt du Tribunal fédéral (recueil officiel)','<p>Décision publiée du Tribunal fédéral suisse, citée par son volume, sa partie et sa page, par exemple ATF 126 V 183 en droit des assurances sociales.</p>','j60-prep')
a('STOP',[('S','Substitution'),('T','mesures Techniques'),('O','mesures Organisationnelles'),('P','mesures Personnelles')],'Principe STOP de la hiérarchie des mesures de protection','<p>Ordre de priorité des mesures de prévention enseigné par la Suva : supprimer ou remplacer le danger, puis le capter techniquement, puis organiser le travail, et enfin seulement protéger la personne par un équipement individuel.</p>','j60-stop')
t('NLST',[('N','National'),('L','Lung'),('S','Screening'),('T','Trial')],'Essai NLST (2011)','<p>Essai américain qui a comparé la tomodensitométrie à faible dose et la radiographie thoracique chez des fumeurs lourds de 55 à 74 ans ; il a montré une baisse de la mortalité par cancer bronchique et fonde le programme de dépistage de la Suva.</p>','j60-ct-suva')
a('J61.0',[('J61.0','code CIM-10-GM : pneumoconiose due à l’amiante et à d’autres fibres minérales, sans exacerbation aiguë')],'Pneumoconiose due à l’amiante et à d’autres fibres minérales, sans mention d’exacerbation aiguë','<p>Code de l’asbestose stable (CIM-10-GM 2024).</p>')
a('J61.1',[('J61.1','code CIM-10-GM : pneumoconiose due à l’amiante et à d’autres fibres minérales, avec exacerbation aiguë')],'Pneumoconiose due à l’amiante et à d’autres fibres minérales, avec mention d’exacerbation aiguë','<p>Code de l’asbestose qui s’aggrave de façon aiguë (CIM-10-GM 2024).</p>','j60-ex-aigue')
a('J62.0',[('J62.0','code CIM-10-GM : pneumoconiose due à la poussière de talc')],'Pneumoconiose due à la poussière de talc','<p>Talcose (CIM-10-GM 2024).</p>','j60-talc')
a('J62.8',[('J62.8','code CIM-10-GM : pneumoconiose due à d’autres poussières de silice')],'Pneumoconiose due à d’autres poussières de silice','<p>Code de la silicose sans autre précision, y compris la silicose aux pierres artificielles (CIM-10-GM 2024).</p>','j60-formes-silicose')
a('J63.0',[('J63.0','code CIM-10-GM : aluminose du poumon')],'Aluminose (du poumon)','<p>Fibrose pulmonaire due à la poudre d’aluminium (CIM-10-GM 2024).</p>','j60-alu')
a('J63.1',[('J63.1','code CIM-10-GM : fibrose du poumon due à la bauxite')],'Fibrose (du poumon) due à la bauxite','<p>Maladie de Shaver, décrite chez les ouvriers de la fusion de la bauxite (CIM-10-GM 2024).</p>','j60-alu')
a('J63.2',[('J63.2','code CIM-10-GM : bérylliose')],'Bérylliose','<p>Granulomatose pulmonaire d’hypersensibilité au béryllium (CIM-10-GM 2024).</p>','j60-berylliose')
a('J63.3',[('J63.3','code CIM-10-GM : fibrose du poumon due au graphite')],'Fibrose (du poumon) due au graphite','<p>Pneumoconiose proche de celle des houilleurs (CIM-10-GM 2024).</p>','j60-inertes')
a('J63.4',[('J63.4','code CIM-10-GM : sidérose')],'Sidérose','<p>Pneumoconiose par oxydes de fer, peu ou pas fibrogène (CIM-10-GM 2024).</p>','j60-inertes')
a('J63.5',[('J63.5','code CIM-10-GM : stannose')],'Stannose','<p>Pneumoconiose par oxyde d’étain, non fibrogène (CIM-10-GM 2024).</p>','j60-inertes')
a('J63.8',[('J63.8','code CIM-10-GM : pneumoconiose due à d’autres poussières inorganiques précisées')],'Pneumoconiose due à d’autres poussières inorganiques précisées','<p>Code des métaux durs, de la barytose et des silicates non nommés ailleurs (CIM-10-GM 2024).</p>','j60-metaux-durs')
a('Isoniaz-TB',[('Isoniaz','ISONIAZide'),('TB','TuBerculose ; nom de spécialité suisse, non strictement lettre à lettre')],'Isoniaz-TB (isoniazide, Labatec Pharma)','<p>Spécialité suisse d’isoniazide en comprimés sécables de 100 et 300 mg ; information professionnelle mise à jour en février 2026.</p>','j60-d-inh')
